  /* 🐧字体使用 */
  body {
    font-family: var(--font1);
    font-weight: normal;
  }

  /* 🐦顶栏 */
  /* 去顶栏阴影 */
  #top-bar {
    box-shadow: none !important;
  }

/* 顶栏透明 */
body.no-blur #top-bar {
    background-color: transparent !important;
}
  #top-settings-holder,
  #top-settings-holder .drawer,
  #top-settings-holder .drawer-toggle,
  #top-settings-holder .drawer-header,
  #top-bar {
      background-color: transparent !important; 
      background: transparent !important;
      box-shadow: none !important;
      border: none !important;
      backdrop-filter: none !important; 
      -webkit-backdrop-filter: none !important;
  }

  /* 允许溢出 */
  #top-settings-holder {
      position: relative; 
      overflow: visible !important; 
  }

  /* 顶栏背景 */
  #top-settings-holder::before {
      content: "";
      position: absolute;
      width: var(--顶栏背景图宽度);
      height: var(--顶栏背景图高度);
      background-image: url("https://iili.io/BMrDZOv.png");
      background-size: 100% auto; 
      background-repeat: no-repeat;
      background-position: center top; 
      top: var(--顶栏背景图上下); 
      left: var(--顶栏背景图左右);
      pointer-events: none; 
      z-index: -1 !important;
  }

  /* 图标居中 */
  #top-settings-holder > div {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
  }

  /* 原始顶栏图标大小 */
  #top-settings-holder .drawer-icon::before {
    font-size: var(--顶栏图标大小);
  }

  /* 隐藏顶栏图标 */
  #top-settings-holder > div > :first-child {
    background-color: transparent !important;
    box-shadow: none !important;
    border: none !important;
    /* 图标 */
    background-size: var(--顶栏图标尺寸) auto !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    /* 框大小 */
    width: var(--顶栏图标宽度) !important;
height: var(--顶栏图标高度) !important;
margin-top:var(--顶栏图标上下) !important;
  }
  #top-settings-holder .drawer-icon::before,
  #top-settings-holder .drawer-icon:hover::before,
  #top-settings-holder .drawer-icon:not(.closedIcon)::before {
    opacity: 0 !important;
    visibility: hidden !important;
  }
  /* 顶栏图标替换 */
  #top-settings-holder > .drawer:nth-of-type(1) .drawer-toggle { background-image: url("https://iili.io/BM67Knj.png") !important; 
margin-top:5px !important;
  transform: scale(1.5) !important;
}
  #top-settings-holder > .drawer:nth-of-type(2) .drawer-toggle { background-image: url("https://iili.io/BMPx88u.png") !important; 
margin-top:2px !important;
  transform: scale(1.2) !important;
}
  #top-settings-holder > .drawer:nth-of-type(4) .drawer-toggle { background-image: url('https://iili.io/BMiz84S.png') !important; 
margin-top:0px !important;
  transform: scale(1.4) !important;
}
  #top-settings-holder > .drawer:nth-of-type(6) .drawer-toggle { background-image: url('https://iili.io/BMsgZNV.png') !important; 
margin-top:1px !important;
  transform: scale(1.3) !important;
}
  #top-settings-holder > .drawer:nth-of-type(7) .drawer-toggle { background-image: url('https://iili.io/BMQoVrN.png') !important; 
margin-top:0px !important;
  transform: scale(1.1) !important;
}
  #top-settings-holder > .drawer:nth-of-type(9) .drawer-toggle { background-image: url('https://iili.io/BMZNAQe.png') !important; 
margin-top:0px !important;
  transform: scale(1.2) !important;
}
  #top-settings-holder > .drawer:nth-of-type(11) .drawer-toggle { background-image: url('https://iili.io/BMtKhmb.png') !important; 
margin-top:p0x !important;
  transform: scale(1.3) !important;
}

    /* 悬停/选中时仅显示选中图标 */
  #top-settings-holder .drawer-toggle:has(.drawer-icon:hover),
  #top-settings-holder .drawer-toggle:has(.drawer-icon:not(.closedIcon)) {
    background-image: none !important;
  }


  /* 悬停和选中顶栏图标 */
  #top-settings-holder .drawer-icon:hover,
  #top-settings-holder .drawer-icon:not(.closedIcon) {
      background-image: url("https://iili.io/BMtc1CN.png") !important;
      width:var(--悬停和选中顶栏图标宽度) !important;
      height: var(--悬停和选中顶栏图标高度) !important;
      background-size: contain;
      background-repeat: no-repeat;
      background-position: center;
      opacity: 1 !important;
margin-top:5px !important;
  transform: scale(1.3) !important;
  }

/* 🐤聊天区域 */
  /* 去聊天背景颜色 聊天居中*/
  #chat {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow: none !important;
    /* 居中 */
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    background-color: transparent;
  }

  /* 气泡与底部距离*/
  #chat {
    padding-bottom: var(--气泡与底部距离) !important;
  }

  /* 消息顶部留空 */
  .mes {
    top: var(--消息顶部留空);
    position: relative !important;
  }

  /* 消息留空 */
  .mes + .mes {
    margin-top: var(--消息留空);
  }

  /* 气泡 */
  .mes {
    align-self: center !important;
    display: flex !important;
    padding-top: var(--气泡上边距) !important;
    padding-bottom: var(--气泡下边距) !important;
    padding-left: var(--气泡左边距) !important;
    padding-right: var(--气泡右边距) !important;
    flex-direction: column !important;
    overflow: visible !important; /* 允许溢出 */
      width: 100%;
    background-image:
      url("https://iili.io/BV7SvRa.png"),
      url("https://iili.io/BV5MNR9.png"),
      url("https://iili.io/BVAiltf.png");
    background-size: 100% auto, 100% auto, 100% auto;
    background-repeat: no-repeat, no-repeat, repeat-y;
    background-position: bottom center, top center, top center;
  }

  .mes_block {
      overflow: visible !important; /* 允许溢出 */
  }


body.bubblechat .mes {
    border-radius: 0px !important;
}

/* 顶部装饰 */
  .mes::before {
    content: "";
    position: absolute !important;
    background-image: url("https://iili.io/BVB87ea.png");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: bottom center;
    width: var(--顶部装饰宽度);
    height: var(--顶部装饰高度);
    bottom: var(--顶部装饰上下);
    left: var(--顶部装饰左右);
    right: var(--顶部装饰左右);
    pointer-events: none;
    z-index: 1;
  }

/* 底部装饰 */
  .mes::after {
    content: "";
    position: absolute !important;
    background-image: url("https://iili.io/BVxp079.png");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: top center;
    width: var(--底部装饰宽度);
    height: var(--底部装饰高度);
    top: var(--底部装饰上下);
    left: var(--底部装饰左右);
    right: var(--底部装饰左右);
    pointer-events: none;
    z-index: 1;
  }

  /* 尾部文字 */
  .mes_block::before {
      content: var(--尾部文字);
      position: absolute !important;
      bottom: var(--尾部文字上下) !important;
      left: var(--尾部文字左右) !important;
      font-family: var(--font1) !important;
      color: var(--color4) !important;
      font-size: var(--尾部文字大小) !important;
      white-space: nowrap !important;
      pointer-events: none !important;
    z-index: 2;
  }


  /* 🌵头像区域 */
/* 头像区域整体 */
.mesAvatarWrapper {
  position: absolute !important;
  top: var(--头像区域整体上下) !important;
  left: var(--头像区域整体左右) !important;
  right: 0 !important;
  width: 100% !important;
  margin: 0 !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: flex-start !important;
  flex-wrap: nowrap !important;
  height: auto !important;
}

/* 头像 */
.mesAvatarWrapper .avatar {
  position: absolute !important;
  top: var(--头像上下) !important;
  transform: translateY(-100%) !important;
  left: var(--头像左右) !important;
  border-radius: 0 !important;
  border: 0px !important;
  width: var(--头像宽度) !important;
  height: var(--头像高度) !important;
  aspect-ratio: var(--头像宽高比) / 1;
  overflow: visible !important;
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  filter: grayscale(0%) !important;
  z-index: 0 !important;
}

/* 头像图片 */
.mesAvatarWrapper .avatar img {
  border: 0px !important;
  border-radius: 0px !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  object-position: var(--头像图片位置) !important;
  box-shadow: none !important;
}

  /* 信息 */
  .mesAvatarWrapper .mesIDDisplay,
  .mesAvatarWrapper .mes_timer,
  .mesAvatarWrapper .tokenCounterDisplay {
    position: relative !important;
    top: var(--信息上下) !important;
    color: var(--color3) !important;
    text-shadow: none !important;
    margin: 0px !important;
    padding: 0px !important;
    line-height: 1 !important;
    font-weight: normal !important;
    opacity: 1 !important;
    text-align: center !important;
    width: 35px !important;
    white-space: nowrap !important; /* 不换行 */
    font-size: var(--信息字体大小) !important;
  }

  .mesAvatarWrapper .mesIDDisplay {
    margin-left: auto !important;
  }

  .mesAvatarWrapper .tokenCounterDisplay {
    margin-right: 3.3% !important;
  }

  /* 🕊️名字和时间戳 */
  /* 名字和时间戳 */
  .mes .ch_name.flex-container {
    position: absolute !important;
    top: 0px !important;
    left: 0px !important;
    right: 0 !important;
    width: 100% !important;
    margin: 0 !important;
    justify-content: flex-start !important;
    align-items: flex-start !important;
  }

  /* 名字 */
  .mes .ch_name.flex-container .name_text {
    text-shadow: none !important;
    font-weight: normal !important;
    color: var(--color5) !important;
    font-style: normal !important;
    text-decoration: none !important;
    letter-spacing: normal !important;
    font-size: var(--名字字体大小) !important;
    position: absolute !important;
    top: var(--名字上下) !important;
    left: var(--名字左右) !important; 
    display: inline-block !important;
    height: auto !important;
    opacity: 1 !important;
    white-space: nowrap !important;
    text-align: left !important;
width:auto;
  }

  /* 自定义字 */
  .ch_name.flex-container .name_text::after {
    content: var(--自定义字) !important;
    font-size: 9px !important;
    margin-left: 2px  !important; 
    color: var(--color6) !important;
  }

  /* 时间戳 */
  .mes .ch_name.flex-container .timestamp {
    position: absolute !important;
    color: var(--color5) !important;
    text-shadow: none !important;
    font-weight: normal !important;
    font-style: normal !important;
    text-decoration: none !important;
    letter-spacing: normal !important;
    font-size: var(--时间戳字体大小) !important;
    position: absolute !important;
    top: var(--时间戳上下) !important;
    right: var(--时间戳左右) !important;
width:auto;
    display: inline-block !important;
    opacity: 1 !important;
    text-align: right !important;
  }

  /* 小幽灵 */
  .mes_ghost.fa-ghost[title][data-i18n] {
    position: relative !important;
    margin-left: 4px !important;
    width: var(--小幽灵宽度) !important;
    height: var(--小幽灵高度) !important;
    transform: translate(var(--小幽灵左右), var(--小幽灵上下)) !important;
    color: transparent !important;
    background-image: url("https://iili.io/BWEShzb.png");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
  z-index: 3 !important;
  }

  /* 🌿思维链 */
   /* 思维链按钮 */
  .mes_reasoning_header.flex-container {
    /* 位置 */
    position: absolute !important;
    top: var(--思维链上下) !important;
    left: var(--思维链左右) !important;
    transform: none !important;
    /* 宽度 */
    width: var(--思维链宽度) !important;
    background-color: transparent !important;
    border-radius: 0 !important;
    padding: 5px 10px !important;
    /* 居中对齐 */
    justify-content: center !important;
    align-items: left !important;
  }

  /* 隐藏原有箭头图标 */
  .mes_reasoning_header.flex-container .mes_reasoning_arrow {
    display: none !important;
  }

  /* 思维链文字 */
  .mes_reasoning_header_title {
    color: var(--color7) !important;
    /* 隐藏原有文字 */
    visibility: hidden !important;
    position: relative !important;
    width: 100% !important;
    text-align: center !important;
    /* 控制新文字大小 */
    font-size: var(--思维链文字大小) !important;
  }

  /* 使用伪元素替换文字 */
  .mes_reasoning_header_title::after {
    content: var(--思维链文字);
    visibility: visible !important;
    position: absolute !important;
    left: 0 !important;
    right: 0 !important;
    top: 0 !important;
    text-align: left !important;
  }

  /* 思维链框 */
  .mes_reasoning {
    background-color:  var(--color8) !important;
    border: 3px double var(--color3) !important;
    color: var(--color5) !important;
    border-radius: 0px;
    font-family: var(--font1) !important;
    padding: 5px 10px !important;
    margin-top: 5px !important;
    margin-bottom: 10px !important;
      box-shadow: 2px 2px 5px var(--color9) !important;
  }

  /* ☘️按钮 */
  /* 按钮组 */
  .mes_buttons {
    position: absolute !important;
    top: var(--按钮组上下) !important;
    right: var(--按钮组左右) !important;
    display: flex !important;
    justify-content: flex-end !important;
    /* 去除阴影 */
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;
    backdrop-filter: none !important;
    overflow: visible !important;
    z-index: 1;
gap: var(--按钮间距) !important; 
  }

  /* 去除效果 */
  .mes_buttons .mes_button {
    opacity: 1 !important; /* 不透明 */
    box-shadow: none !important; /* 无阴影 */
    text-shadow: none !important;
    transition: none !important; /* 去除动画过渡 */
    filter: none !important;
    backdrop-filter: none !important;
    border-radius: 0 !important; /* 防止圆形裁剪 */
    overflow: visible !important; /* 允许图标完整显示 */
  }

  /* 悬停发光 */
  .mes_buttons .mes_button:hover {
    filter: drop-shadow(0 0 5px var(--color10)) !important;
  }

